const std = @import("std");

pub fn main() void {
    // const = immutable, var = mutable
    const x: i32 = 42;
    var y: i32 = 10;
    y += 1;

    // Type inference
    const z = 3.14;   // f64 inferred
    const b = true;   // bool

    // Integer types
    // Signed:   i8 i16 i32 i64 i128 isize
    // Unsigned: u8 u16 u32 u64 u128 usize
    // Arbitrary: i7, u13 etc. — any bit width!
    const byte: u8 = 255;
    const big: u128 = 1;
    const ptr_sz: usize = @sizeOf(usize);

    // Float types: f16 f32 f64 f80 f128
    const pi: f64 = 3.14159265358979;

    // Arithmetic (no overflow by default in debug mode!)
    const sum = x + y;
    const wrapped = @addWithOverflow(x, y);  // explicit wrapping
    const sat = @as(u8, 200) +| 100;   // saturating: 255
    const wrap = @as(u8, 200) +% 100;  // wrapping: 44

    // Bitwise
    const a = x & y;   // AND
    const o = x | y;   // OR
    const xr = x ^ y;  // XOR
    const sh = x << 2; // shift left
    const nb = ~x;     // NOT

    std.debug.print("x={} y={} sum={}\n", .{x, y, sum});
    _ = .{z, b, byte, big, ptr_sz, pi, a, o, xr, sh, nb, wrapped, sat, wrap};
}
