const std = @import("std");

// Error sets
const MathError = error{
    DivisionByZero,
    Overflow,
};

const FileError = error{
    NotFound,
    PermissionDenied,
};

// Error union type: !T or ErrorSet!T
fn divide(a: i32, b: i32) MathError!i32 {
    if (b == 0) return MathError.DivisionByZero;
    return @divTrunc(a, b);
}

// Function returning anyerror (inferred error set)
fn readFile(path: []const u8) ![]u8 {
    _ = path;
    return FileError.NotFound;
}

pub fn main() !void {
    // try — propagate error (return if err)
    const result = try divide(10, 2);
    std.debug.print("result: {}\n", .{result});

    // catch — handle error
    const safe = divide(10, 0) catch |err| blk: {
        std.debug.print("Error: {}\n", .{err});
        break :blk -1;
    };
    std.debug.print("safe: {}\n", .{safe});

    // catch with unreachable (assert never errors)
    const r2 = divide(6, 2) catch unreachable;
    _ = r2;

    // if with error union
    if (divide(10, 0)) |val| {
        std.debug.print("Got {}\n", .{val});
    } else |err| {
        std.debug.print("Err: {}\n", .{err});
    }

    // errdefer — run cleanup on error return
    // errdefer allocator.free(buffer);
}
