const std = @import("std");

pub fn main() !void {
    // Zig has no default allocator — you choose!

    // GeneralPurposeAllocator — detects leaks in debug
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();   // check for leaks on exit
    const allocator = gpa.allocator();

    // Allocate a single item
    const n = try allocator.create(i32);
    defer allocator.destroy(n);
    n.* = 42;
    std.debug.print("n = {}\n", .{n.*});

    // Allocate a slice (array)
    const buf = try allocator.alloc(u8, 100);
    defer allocator.free(buf);
    buf[0] = 'H';
    buf[1] = 'i';

    // Resize
    const buf2 = try allocator.realloc(buf, 200);
    defer allocator.free(buf2);

    // ArrayList — dynamic array
    var list = std.ArrayList(i32).init(allocator);
    defer list.deinit();

    try list.append(1);
    try list.append(2);
    try list.append(3);
    std.debug.print("len = {}\n", .{list.items.len});

    // HashMap
    var map = std.StringHashMap(i32).init(allocator);
    defer map.deinit();
    try map.put("one", 1);
    try map.put("two", 2);
    if (map.get("one")) |v| {
        std.debug.print("one = {}\n", .{v});
    }

    // Arena allocator — free all at once (great for request/frame)
    var arena = std.heap.ArenaAllocator.init(allocator);
    defer arena.deinit();   // frees ALL allocations at once
    const ar = arena.allocator();
    const s = try ar.alloc(u8, 50);
    _ = s;  // freed by arena.deinit()
}
