const std = @import("std");

// Struct
const Point = struct {
    x: f64,
    y: f64,

    // Methods — no implicit self, must pass explicitly
    pub fn distance(self: Point, other: Point) f64 {
        const dx = self.x - other.x;
        const dy = self.y - other.y;
        return @sqrt(dx * dx + dy * dy);
    }

    pub fn origin() Point {
        return .{ .x = 0, .y = 0 };
    }
};

// Enum
const Direction = enum {
    north, south, east, west,

    pub fn opposite(self: Direction) Direction {
        return switch (self) {
            .north => .south,
            .south => .north,
            .east  => .west,
            .west  => .east,
        };
    }
};

// Tagged union
const Shape = union(enum) {
    circle:    struct { radius: f64 },
    rectangle: struct { width: f64, height: f64 },

    pub fn area(self: Shape) f64 {
        return switch (self) {
            .circle    => |c| std.math.pi * c.radius * c.radius,
            .rectangle => |r| r.width * r.height,
        };
    }
};

pub fn main() void {
    const p1 = Point.origin();
    const p2 = Point{ .x = 3, .y = 4 };
    std.debug.print("dist: {d}\n", .{p1.distance(p2)});  // 5

    const d = Direction.north;
    std.debug.print("opp: {}\n", .{d.opposite()});  // south

    const c = Shape{ .circle = .{ .radius = 5 } };
    std.debug.print("area: {d}\n", .{c.area()});  // ~78.54
}
