const std = @import("std");

// comptime parameters — generics in Zig!
fn Stack(comptime T: type) type {
    return struct {
        items: std.ArrayList(T),

        const Self = @This();

        pub fn init(allocator: std.mem.Allocator) Self {
            return .{ .items = std.ArrayList(T).init(allocator) };
        }

        pub fn deinit(self: *Self) void { self.items.deinit(); }

        pub fn push(self: *Self, item: T) !void {
            try self.items.append(item);
        }

        pub fn pop(self: *Self) ?T {
            return self.items.popOrNull();
        }
    };
}

// comptime function — evaluated at compile time
fn factorial(comptime n: u64) u64 {
    if (n <= 1) return 1;
    return n * factorial(n - 1);
}

// comptime if — conditional compilation
fn platformMessage() []const u8 {
    return if (@import("builtin").os.tag == .windows)
        "Running on Windows"
    else
        "Running on Unix";
}

// comptime types
fn maxVal(comptime T: type) T {
    return std.math.maxInt(T);
}

pub fn main() !void {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const alloc = gpa.allocator();

    // Generic stack
    var int_stack = Stack(i32).init(alloc);
    defer int_stack.deinit();
    try int_stack.push(1);
    try int_stack.push(2);
    std.debug.print("popped: {}\n", .{int_stack.pop().?});  // 2

    // Compile-time computation
    const f5 = factorial(10);  // computed at compile time!
    std.debug.print("10! = {}\n", .{f5});
    std.debug.print("u8 max: {}\n", .{maxVal(u8)});   // 255
    std.debug.print("i32 max: {}\n", .{maxVal(i32)}); // 2147483647
    std.debug.print("{s}\n", .{platformMessage()});
}
