const std = @import("std");

pub fn main() void {
    // Arrays (fixed size, known at compile time)
    const arr = [5]i32{ 1, 2, 3, 4, 5 };
    const arr2 = [_]i32{ 10, 20, 30 };  // infer length
    std.debug.print("len: {}\n", .{arr.len});

    // Slices — pointer + length, runtime size
    const slice: []const i32 = &arr;
    const sub = arr[1..4];    // {2, 3, 4}
    std.debug.print("slice[0]: {}\n", .{slice[0]});
    std.debug.print("sub len: {}\n", .{sub.len});

    // Mutable slice
    var buf = [_]u8{ 1, 2, 3, 4, 5 };
    const mslice: []u8 = &buf;
    mslice[0] = 99;

    // String literals are []const u8
    const s: []const u8 = "Hello, Zig!";
    std.debug.print("{s}\n", .{s});

    // Pointers
    var x: i32 = 42;
    const ptr: *i32 = &x;   // single-item pointer
    ptr.* = 99;              // dereference with .*
    std.debug.print("x = {}\n", .{x});

    // Optional — nullable value (?T)
    var maybe: ?i32 = 42;
    var nothing: ?i32 = null;

    // Unwrap optional
    if (maybe) |val| {
        std.debug.print("got: {}\n", .{val});
    }

    // orelse — default value
    const val = maybe orelse 0;     // 42
    const val2 = nothing orelse 0;  // 0

    // Unwrap or unreachable
    const v = maybe.?;   // panics if null!

    _ = .{arr2, val, val2, v};
}
